import { useEffect, useRef, useState } from 'react';
import * as fabric from 'fabric';
import { WidgetProps } from './Widget';
import { ImageViewerFullScreen } from './ImageViewerFullScreen';
import {
  generateHeatmap,
  drawColorBar,
  COLORMAP_OPTIONS,
  Colormap
} from './heatmapUtils';

const HEATMAP_ICON_PATH =
  'data:image/png;base64,';
const LASER_DOT_IMAGE =
  'data:image/png;base64,';

interface IImageViewerProps extends WidgetProps {
  value?: {
    imageUrl: string;
    dimensions?: {
      width: number;
      height: number;
    };
    differences?: number[];
  };
  heatmapOverlay?: boolean;
  isBinary?: boolean;
}

interface ILaserDotImage extends fabric.FabricImage {
  isLaserDot?: boolean;
}

export default function ImageViewer({
  value,
  editorContext,
  heatmapOverlay,
  isBinary
}: IImageViewerProps): JSX.Element {
  const canvasElParent = useRef<HTMLDivElement>(null);
  const canvasElement = useRef<HTMLCanvasElement>(null);
  const canvas = useRef<fabric.Canvas | null>(null);
  const colorBarRef = useRef<HTMLCanvasElement>(null);
  const isPanning = useRef(false);
  const lastPosX = useRef(0);
  const lastPosY = useRef(0);

  const [image, setImage] = useState<fabric.FabricImage | null>(null);
  const [lastValidImageUrl, setLastValidImageUrl] = useState<string>();
  const [showHeatmap, setShowHeatmap] = useState(false);
  const [selectedColormap, setSelectedColormap] = useState<Colormap>('viridis');
  const [lastValidDimensions, setLastValidDimensions] = useState<{
    width: number;
    height: number;
  } | null>(null);
  const [isFullScreen, setIsFullScreen] = useState(false);

  useEffect(() => {
    if (value?.dimensions) {
      setLastValidDimensions(value.dimensions);
    }
  }, [value?.dimensions]);

  useEffect(() => {
    if (value?.imageUrl) {
      setLastValidImageUrl(value.imageUrl);
    }
  }, [value?.imageUrl]);

  const updateGlobalTransform = () => {
    if (!editorContext) {
      return;
    }
    const viewportTransform = canvas.current!.viewportTransform;
    editorContext.updateGlobalTransform({
      x: viewportTransform[4],
      y: viewportTransform[5],
      zoom: canvas.current?.getZoom() ?? 1
    });
  };

  const updateLastPox = (x: number, y: number) => {
    lastPosX.current = x;
    lastPosY.current = y;
    updateGlobalTransform();
  };

  function resizeCanvas() {
    const parent = canvasElParent.current;
    canvas.current?.setDimensions({
      width: parent?.clientWidth ?? 0,
      height: parent?.clientHeight ?? 0
    });
    canvas.current?.renderAll();
  }

  useEffect(() => {
    if (!canvasElement.current || !canvasElParent.current) {
      return;
    }

    canvas.current = new fabric.Canvas(canvasElement.current, {
      selection: false
    });

    canvas.current.on('mouse:down', opt => {
      isPanning.current = true;
      const pointer = canvas.current!.getScenePoint(opt.e);
      updateLastPox(pointer.x, pointer.y);
    });

    canvas.current.on('mouse:move', opt => {
      if (isPanning.current && canvas.current) {
        const viewportTransform = canvas.current!.viewportTransform;
        const pointer = canvas.current!.getScenePoint(opt.e);
        viewportTransform[4] += pointer.x - lastPosX.current;
        viewportTransform[5] += pointer.y - lastPosY.current;
        canvas.current?.renderAll();
        updateLastPox(pointer.x, pointer.y);
      }
    });

    canvas.current.on('mouse:up', () => {
      isPanning.current = false;
    });

    canvas.current.on('mouse:wheel', opt => {
      if (!canvas.current) {
        return;
      }
      const delta = opt.e.deltaY;
      let zoom = canvas.current!.getZoom();
      zoom *= 0.999 ** delta;
      zoom = Math.max(0.05, zoom);
      zoom = Math.min(5, zoom);
      const deltaPoint = new fabric.Point(opt.e.offsetX, opt.e.offsetY);
      canvas.current.zoomToPoint(deltaPoint, zoom);
      opt.e.preventDefault();
      opt.e.stopPropagation();
      updateGlobalTransform();
    });

    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);
    return () => {
      canvas.current?.dispose();
      window.removeEventListener('resize', resizeCanvas);
    };
  }, []);

  useEffect(() => {
    if (!canvas.current || !lastValidImageUrl) {
      return;
    }
    canvas.current.clear();
    fabric.FabricImage.fromURL(lastValidImageUrl)
      .then((img: fabric.Image) => {
        if (canvas.current?.backgroundImage === img) {
          return;
        }
        setImage(img);
      })
      .catch(err => {
        console.error('Failed to load image', err);
      });
  }, [lastValidImageUrl]);

  useEffect(() => {
    if (!canvas.current || !image) {
      return;
    }

    const {
      x: asyncX,
      y: asyncY,
      zoom: asyncZoom
    } = editorContext?.getImageViewTransform() ?? {};

    const scaleFactor =
      asyncZoom ??
      Math.min(
        canvas.current!.width / image.width,
        canvas.current!.height / image.height
      );
    canvas.current!.setZoom(scaleFactor);

    // Set background image
    canvas.current!.backgroundImage = image;

    // Heatmap overlay
    if (showHeatmap && value?.differences) {
      try {
        const heatmapImage = generateHeatmap(
          value.differences,
          image.width,
          image.height,
          selectedColormap,
          isBinary ?? false
        );

        heatmapImage.scaleX = image.width / (heatmapImage.width ?? 1);
        heatmapImage.scaleY = image.height / (heatmapImage.height ?? 1);
        heatmapImage.opacity = isBinary ? 1.0 : 0.3;

        if (canvas.current) {
          canvas.current.overlayImage = heatmapImage;
          canvas.current.renderAll();
        }
      } catch (error) {
        console.error('Failed to process differences data:', error);
      }
    } else {
      if (canvas.current) {
        canvas.current.overlayImage = undefined;
        canvas.current.renderAll();
      }
    }

    const zoom = canvas.current!.getZoom();
    const viewportTransform = canvas.current!.viewportTransform;

    // Calculate the translation to center the image
    const centerX = (canvas.current!.width - image.width * zoom) / 2;
    const centerY = (canvas.current!.height - image.height * zoom) / 2;

    if (viewportTransform) {
      viewportTransform[4] = asyncX ?? centerX;
      viewportTransform[5] = asyncY ?? centerY;
    }

    canvas.current!.renderAll();
  }, [
    editorContext?.getImageViewTransform(),
    image,
    showHeatmap,
    selectedColormap,
    value?.differences,
    isBinary
  ]);

  useEffect(() => {
    const ctx = colorBarRef.current?.getContext('2d');
    if (ctx && showHeatmap) {
      drawColorBar(ctx, isBinary ?? true, selectedColormap);
    }
  }, [showHeatmap, selectedColormap, isBinary]);

  useEffect(() => {
    if (!canvas.current || !image || !value?.differences) {
      return;
    }

    if (showHeatmap) {
      const heatmapImage = generateHeatmap(
        value.differences,
        image.width!,
        image.height!,
        selectedColormap,
        isBinary ?? true
      );

      heatmapImage.scaleX = image.width / (heatmapImage.width ?? 1);
      heatmapImage.scaleY = image.height / (heatmapImage.height ?? 1);
      heatmapImage.opacity = isBinary ? 1.0 : 0.3;

      if (canvas.current) {
        canvas.current.overlayImage = heatmapImage;
        canvas.current.renderAll();
      }
    } else {
      if (canvas.current) {
        canvas.current.overlayImage = undefined;
        canvas.current.renderAll();
      }
    }
  }, [image, showHeatmap, value?.differences, selectedColormap, isBinary]);

  useEffect(() => {
    if (!canvas.current || !image) {
      return;
    }

    const mousePos = editorContext?.getMousePosition() ?? {};

    if (mousePos.x !== undefined && mousePos.y !== undefined) {
      // Remove any existing laser dots
      const objects = canvas.current.getObjects();
      objects.forEach(obj => {
        if (
          obj instanceof fabric.FabricImage &&
          'isLaserDot' in obj &&
          (obj as ILaserDotImage).isLaserDot
        ) {
          canvas.current?.remove(obj);
        }
      });

      // Laser dot
      fabric.FabricImage.fromURL(LASER_DOT_IMAGE)
        .then((img: fabric.FabricImage) => {
          img.set({
            left: mousePos.x,
            top: mousePos.y,
            originX: 'center',
            originY: 'center',
            selectable: false,
            evented: false,
            scaleX: 0.05,
            scaleY: 0.05
          });

          (img as ILaserDotImage).isLaserDot = true;
          canvas.current?.add(img);
          canvas.current?.renderAll();
        })
        .catch(err => {
          console.error('Failed to load laser dot image:', err);
        });
    } else {
      // Remove laser dot when no mouse position
      const objects = canvas.current.getObjects();
      objects.forEach(obj => {
        if (
          obj instanceof fabric.FabricImage &&
          'isLaserDot' in obj &&
          (obj as ILaserDotImage).isLaserDot
        ) {
          canvas.current?.remove(obj);
        }
      });
      canvas.current.renderAll();
    }
  }, [editorContext?.getMousePosition(), image]);

  useEffect(() => {
    if (!canvas.current) {
      return;
    }

    const handleMouseMove = (opt: fabric.TEvent) => {
      if (!canvas.current || !editorContext) {
        return;
      }

      const pointer = canvas.current.getScenePoint(opt.e);
      editorContext.updateMousePosition({
        x: pointer.x,
        y: pointer.y
      });
    };

    const handleMouseLeave = () => {
      if (!editorContext) {
        return;
      }
      editorContext.updateMousePosition({
        x: undefined,
        y: undefined
      });
    };

    canvas.current.on('mouse:move', handleMouseMove);
    canvas.current.on('mouse:out', handleMouseLeave);

    return () => {
      canvas.current?.off('mouse:move', handleMouseMove);
      canvas.current?.off('mouse:out', handleMouseLeave);
    };
  }, [editorContext]);

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        width: '100%',
        height: '100%',
        gap: '1px'
      }}
    >
      {lastValidDimensions && (
        <div
          className="nodrag nowheel"
          style={{
            textAlign: 'center',
            fontSize: 'var(--vpl-ui-font-size1)',
            fontFamily: 'var(--vpl-ui-font-family)',
            color: 'var(--vpl-ui-font-color2)',
            minHeight: '14px',
            padding: '2px 0',
            userSelect: 'none',
            pointerEvents: 'none',
            position: 'relative',
            zIndex: 1
          }}
        >
          {`${lastValidDimensions.width} x ${lastValidDimensions.height}`}
        </div>
      )}
      {/* Main canvas container */}
      <div
        ref={canvasElParent}
        className={'nodrag nowheel widget common-input-style'}
        style={{
          width: '100%',
          flex: 1,
          padding: 0,
          position: 'relative',
          zIndex: 1
        }}
      >
        <canvas
          ref={canvasElement}
          className={`nodrag nowheel widget imageview ${isPanning.current ? 'grabbing' : 'grab'}`}
        />
      </div>
      {/* Controls container */}
      <div
        className="nodrag nowheel"
        style={{
          display: 'flex',
          justifyContent: 'flex-start',
          alignItems: 'center',
          position: 'relative',
          zIndex: 1,
          backgroundColor: 'var(--vpl-ui-background)',
          height: '44px'
        }}
      >
        {/* Heatmap controls */}
        {lastValidDimensions && heatmapOverlay && (
          <>
            <button
              className={`heatmap-button nodrag ${showHeatmap ? 'active' : ''}`}
              onClick={() => setShowHeatmap(!showHeatmap)}
              title={showHeatmap ? 'Hide heatmap' : 'Show heatmap'}
            >
              <img
                src={HEATMAP_ICON_PATH}
                alt="heatmap toggle"
                className="nodrag"
              />
            </button>

            {!isBinary && showHeatmap && (
              <div style={{ width: '80px', marginLeft: '8px' }}>
                <select
                  className="nodrag common-input-style widget"
                  value={selectedColormap}
                  onChange={e =>
                    setSelectedColormap(e.target.value as Colormap)
                  }
                  style={{ padding: '0px' }}
                >
                  {COLORMAP_OPTIONS.map(cm => (
                    <option key={cm} value={cm}>
                      {cm}
                    </option>
                  ))}
                </select>
              </div>
            )}

            {showHeatmap && (
              <div
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  marginLeft: '8px'
                }}
              >
                <div
                  style={{
                    height: '24px',
                    display: 'flex',
                    alignItems: 'center'
                  }}
                >
                  <canvas
                    ref={colorBarRef}
                    width={isBinary ? 60 : 120}
                    height={20}
                    style={{
                      border: '1px solid var(--vpl-border-light)',
                      borderRadius: '2px'
                    }}
                  />
                </div>
                <div
                  style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    width: isBinary ? '60px' : '120px',
                    marginTop: '1px',
                    fontSize: 'var(--vpl-ui-font-size1)',
                    color: 'var(--vpl-ui-font-color2)'
                  }}
                >
                  {isBinary ? (
                    <>
                      <span>-1</span>
                      <span>0</span>
                      <span>1</span>
                    </>
                  ) : (
                    <>
                      <span>-1</span>
                      <span>1</span>
                    </>
                  )}
                </div>
              </div>
            )}
          </>
        )}

        {/* Fullscreen button*/}
        <button
          className="heatmap-button nodrag"
          onClick={() => {
            setIsFullScreen(true);
          }}
          title="View fullscreen"
          style={{ marginLeft: '8px' }}
        >
          <svg
            width="14"
            height="14"
            viewBox="0 0 14 14"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
          >
            <path
              d="M2 6H0V0H6V2H2V6ZM0 8H2V12H6V14H0V8ZM12 12H8V14H14V8H12V12ZM8 2V0H14V6H12V2H8Z"
              fill="currentColor"
            />
          </svg>
        </button>
      </div>
      {/* Fullscreen portal */}
      {isFullScreen && lastValidImageUrl && (
        <ImageViewerFullScreen
          imageUrl={lastValidImageUrl}
          onClose={() => setIsFullScreen(false)}
          showHeatmap={showHeatmap}
          differences={value?.differences}
          selectedColormap={selectedColormap}
          isBinary={isBinary}
        />
      )}
    </div>
  );
}
